package io.rwagent.client;

import java.util.*;
import static io.rwagent.client.StrategyDirector.map;

/** Focused synthetic mechanics/fog contracts; no native exchange or desktop outcome claim. */
public final class G52FightZonesHarness {
    static int checks;
    static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    static Map<String,Object> packet(){return map("sessionId","s","playerKey","team:0","frame",1L,"gameTimeMs",0L,"catalogGameJarMatched",true,"catalogSha256",TargetCatalog.catalogSha256());}
    static Map<String,Object> target(long id,String type,double hp,boolean armed,boolean building,double x,double y){return map("id",id,"type",type,"hp",hp,"canAttack",armed,"building",building,"x",x,"y",y,"targetDomain","SURFACE","domainObservedAtGameTimeMs",0L,"lastSeenGameTimeMs",0L);}
    static List<Map<String,Object>> army(String type,int n,double hp){List<Map<String,Object>> rows=new ArrayList<Map<String,Object>>();for(int i=0;i<n;i++)rows.add(target(i+10,type,hp,true,false,100,100));return rows;}
    static void profilesAndExchange(){Map<String,Object> p=packet();check(TargetCatalog.available(),"verified catalog resource available");
        CombatProfiles.Profile base=CombatProfiles.get("commandCenter",true);check(base.maxHp==4000&&base.range==280&&base.dps()==60,"native base 4000/280/60 calibration rejects community HP3000");
        Map<String,Object> factory=target(100,"landFactory",12000,false,true,300,100),enemyBase=target(101,"commandCenter",4000,true,true,300,100);
        List<Map<String,Object>> tanks=army("tank",6,210);FightEstimate unarmed=FightEstimate.estimate(tanks,factory,Arrays.asList(factory),p),defended=FightEstimate.estimate(tanks,enemyBase,Arrays.asList(enemyBase),p);
        check(unarmed.known&&unarmed.admitted&&unarmed.enemyDps==0&&unarmed.timeToKillSeconds==100,"thick lawful unarmed building has long TTK and zero invented DPS");
        check(defended.known&&!defended.admitted&&defended.enemyDps==60&&defended.approachExposureSeconds>0,"six light tanks reject native base fire with range approach cost");
        check(FightEstimate.estimate(army("tank",12,210),enemyBase,Arrays.asList(enemyBase),p).admitted,"more compatible observed DPS and HP change admission without fixed army-count rule");
        check(!FightEstimate.estimate(army("tank",6,350),enemyBase,Arrays.asList(enemyBase),p).admitted&&FightEstimate.estimate(army("heavyTank",6,350),enemyBase,Arrays.asList(enemyBase),p).admitted,"equal army count/currentHP different verified DPS flips admission");
        List<Map<String,Object>> equalHp=army("heavyTank",6,210);FightEstimate faster=FightEstimate.estimate(equalHp,enemyBase,Arrays.asList(enemyBase),p);check(faster.timeToKillSeconds<defended.timeToKillSeconds&&faster.expectedLossFraction<defended.expectedLossFraction,"equalHP higherDPS reduces TTK and incoming exchange loss");
        check(!FightEstimate.estimate(army("unknownMod",6,210),enemyBase,Arrays.asList(enemyBase),p).known,"unknown type never becomes known profile");p.put("catalogGameJarMatched",false);check(!FightEstimate.estimate(tanks,enemyBase,Arrays.asList(enemyBase),p).known,"unverified game identity prevents known mechanics");
    }
    static void legalMemory(){BaseThreatZones zones=new BaseThreatZones();Map<String,Object> p=packet(),base=target(101,"commandCenter",4000,true,true,500,100);p.put("visibleEnemies",Arrays.asList(base));zones.observe("s","team:0",1,0,p,true);
        check(zones.view().size()==1&&zones.blocks(100,100,900,100,Collections.<Long>emptySet())==101L,"current legal base creates range-based travel veto");
        p.put("visibleEnemies",Collections.emptyList());p.put("gameTimeMs",1000L);zones.observe("s","team:0",2,1000,p,true);check(zones.view().size()==1,"complete lost-contact packet preserves zone without guessing death");
        check(zones.blocks(100,100,100,1000,Collections.<Long>emptySet())==null,"ordinary legal alternate geometry outside zone remains open");
        check(zones.blocks(700,100,1000,100,Collections.<Long>emptySet())==null,"memory allows continuously outward exit from remembered base circle");
        check(zones.blocks(700,100,0,100,Collections.<Long>emptySet())==101L,"exit across remembered base does not become lawful escape geometry");
        p.put("visibleEnemies",Arrays.asList(target(101,"commandCenter",0,false,true,500,100)));zones.observe("s","team:0",3,2000,p,false);check(zones.view().size()==1,"stale/malformed zero HP cannot clear zone");
        Map<String,Object> dead=target(101,"commandCenter",0,false,true,500,100);dead.put("dead",true);dead.put("lastSeenGameTimeMs",2000L);p.put("gameTimeMs",2000L);p.put("visibleEnemies",Arrays.asList(dead));zones.observe("s","team:0",4,2000,p,true);check(zones.view().isEmpty(),"explicit current legally visible death clears zone");
        p=packet();p.put("visibleEnemies",Arrays.asList(base));zones.observe("s","team:0",5,0,p,true);zones.observe("new","team:0",1,0,packet(),false);check(zones.view().isEmpty(),"session reset clears remembered geometry");zones.reset();check(zones.view().isEmpty(),"explicit reset clears memory");
    }
    static void integration()throws Exception{G5CombatHarness.Fixture light=new G5CombatHarness.Fixture();G51TacticalHarness.catalog(light);for(long id=10;id<16;id++){light.find(id).put("type","tank");light.find(id).put("hp",210);light.find(id).put("maxHp",210);}G51TacticalHarness.enemy(light,201,"commandCenter",1000,100,4000,true,true,"SURFACE");light.collect();check("STANDOFF".equals(light.combat.view(light.a).get("tacticalChoice"))&&!light.combat.retreating(light.a),"poor base exchange rejects objective without sight-only retreat");
        light.enemyRows.clear();light.frontierKnown=true;light.frontierX=1800;light.frontierY=100;light.sample(1000);light.collect();check("STANDOFF".equals(light.combat.view(light.a).get("tacticalChoice")),"lost base memory blocks frontier behind remembered fire zone");for(ForceController.Proposal proposal:light.owned("general:1"))check(proposal.path.startsWith("/command/move?"),"remembered base only permits hold move, never hidden attack");
        G5CombatHarness.Fixture f=new G5CombatHarness.Fixture();CommanderDirector commander=new CommanderDirector(f.registry);f.combat.setCommander(commander);G51TacticalHarness.enemy(f,202,"tank",1700,100,210,true,false,"SURFACE");f.collect();check(f.owned("general:1").isEmpty()&&((Number)f.combat.view(f.a).get("filteredUnassignedTargets")).intValue()==1,"unassigned remote mobile enemy cannot send General across map");
        G5CombatHarness.Fixture remoteBuilding=new G5CombatHarness.Fixture();remoteBuilding.combat.setCommander(new CommanderDirector(remoteBuilding.registry));G51TacticalHarness.enemy(remoteBuilding,205,"commandCenter",1700,100,4000,true,true,"SURFACE");remoteBuilding.collect();check(remoteBuilding.owned("general:1").isEmpty()&&((Number)remoteBuilding.combat.view(remoteBuilding.a).get("filteredUnassignedTargets")).intValue()==1,"remote armed building cannot bypass Commander budget through strategic-building exception");
        G5CombatHarness.Fixture nearBuilding=new G5CombatHarness.Fixture();nearBuilding.combat.setCommander(new CommanderDirector(nearBuilding.registry));G51TacticalHarness.enemy(nearBuilding,206,"landFactory",200,100,1000,false,true,"SURFACE");nearBuilding.collect();check("ADVANCE".equals(nearBuilding.combat.view(nearBuilding.a).get("tacticalChoice")),"nearby current economic building remains local opportunity without remote diversion");
        G5CombatHarness.Fixture nearBuilder=new G5CombatHarness.Fixture();nearBuilder.combat.setCommander(new CommanderDirector(nearBuilder.registry));G51TacticalHarness.enemy(nearBuilder,207,"builder",200,100,170,false,false,"SURFACE");nearBuilder.collect();check("ADVANCE".equals(nearBuilder.combat.view(nearBuilder.a).get("tacticalChoice")),"nearby current unarmed mobile actor may be handled locally without fake threat budget");
        G5CombatHarness.Fixture thick=new G5CombatHarness.Fixture();G51TacticalHarness.catalog(thick);G51TacticalHarness.enemy(thick,203,"landFactory",900,100,12000,false,true,"SURFACE");thick.collect();check("ADVANCE".equals(thick.combat.view(thick.a).get("tacticalChoice")),"native-eligible thick unarmed strategic building remains admitted");
        G5CombatHarness.Fixture revoked=new G5CombatHarness.Fixture();G51TacticalHarness.enemy(revoked,204,"tank",1700,100,210,true,false,"SURFACE");revoked.collect();check("ADVANCE".equals(revoked.combat.view(revoked.a).get("tacticalChoice")),"legacy standalone fixture has an accepted remote advance before Commander filtering is attached");
        for(ForceController.Proposal proposal:revoked.owned("general:1"))proposal.accepted(map("status","queued","frame",revoked.frame,"gameTimeMs",revoked.now));revoked.combat.setCommander(new CommanderDirector(revoked.registry));revoked.sample(1000);revoked.collect();check("COMMANDER_UNASSIGNED_REMOTE_TARGET_ORDER_CANCELLED".equals(revoked.combat.view(revoked.a).get("tacticalReason"))&&revoked.owned("general:1").size()==6,"revoked remote target gets explicit same-owner move cancellation inside accepted advance cooldown");
        for(ForceController.Proposal proposal:revoked.owned("general:1"))check(proposal.path.startsWith("/command/move?")&&proposal.priority==30,"budget revoke uses ordinary General move, not attack or crisis retreat");
    }
    public static void main(String[] args)throws Exception{profilesAndExchange();legalMemory();integration();System.out.println("G52FightZonesHarness checks="+checks+" PASS");}
}
